# Browser launchers
chrome() { google-chrome "$1" & }
firefox() { firefox "$1" & }
brave() { brave-browser "$1" & }
edge() { microsoft-edge "$1" & }
opera() { opera "$1" & }

# Profile-specific launches
chrome-dev() { google-chrome --profile-directory="Profile 1" "$1" & }
firefox-work() { firefox -P work "$1" & }

# Quick access to common sites
codex() { chrome "https://drive.google.com/drive/folders/[CODEX_FOLDER_ID]" & }
github-unexusi() { firefox "https://github.com/[USERNAME]/UNEXUSI" & }
