#!/bin/bash
# browser_launcher.sh

echo "Select browser:"
echo "1) Chrome"
echo "2) Firefox"
echo "3) Brave"
echo "4) Edge"
echo "5) Opera"
read -p "Choice: " choice

read -p "URL: " url

case $choice in
    1) google-chrome "$url" & ;;
    2) firefox "$url" & ;;
    3) brave-browser "$url" & ;;
    4) microsoft-edge "$url" & ;;
    5) opera "$url" & ;;
esac
